export function freshStore(){return {version:1,nextUser:100,accounts:[],posts:[],mail:[],calls:0,autoMessage:{from:'TheOperator',body:'Welcome to The Midnight Relay. Read widely and leave the board better than you found it.'}}}
export function restoreStore(raw){try{const v=JSON.parse(raw);if(v?.version!==1||!Array.isArray(v.accounts)||!Array.isArray(v.posts)||!Array.isArray(v.mail))throw 0;return {...freshStore(),...v,accounts:v.accounts.slice(0,50),posts:v.posts.slice(-200),mail:v.mail.slice(-300)}}catch{return freshStore()}}
export function sanitizeInput(s,max=512){return String(s??'').replace(/[\x00-\x08\x0b-\x1f\x7f\u001b]/g,'').slice(0,max)}
export async function digestPassword(s){const data=new TextEncoder().encode(`midnight-relay:${s}`);if(globalThis.crypto?.subtle){const b=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}let h=2166136261;for(const n of data)h=Math.imul(h^n,16777619);return `local-${(h>>>0).toString(16)}`}
