 textAreas(){this.print('\n'+TEXT_AREAS.map((a,i)=>`${i+1}. ${a.name}`).join('\n')+'\n');this.prompt()},textList(){const a=TEXT_AREAS[this.rt.textArea];this.print(`\n${a.name}\n`+a.files.map((f,i)=>`${i+1}. ${f[0]} — ${f[1]}`).join('\n')+'\n');this.prompt()},textNumber(v){const file=String(v).startsWith('#'),n=+String(v).replace('#','');if(file){const a=TEXT_AREAS[this.rt.textArea];if(n>=1&&n<=a.files.length){this.rt.textFile=n-1;return this.handlers.textRead.call(this)}}else if(n>=1&&n<=TEXT_AREAS.length){this.rt.textArea=n-1;this.rt.textFile=0;return this.handlers.textList.call(this)}this.print('\nNo such area or file. Use a number for an area, or #number to read a file.\n');this.prompt()},textRead(){const f=TEXT_AREAS[this.rt.textArea].files[this.rt.textFile];if(!f)return this.prompt();this.print(`\n${f[0]} — ${f[1]}\n${'-'.repeat(55)}\n${f[2]}\n${f[3]?`Accessible description: ${f[3]}\n`:''}`);this.prompt()},textNext(){const a=TEXT_AREAS[this.rt.textArea];this.rt.textFile=(this.rt.textFile+1)%a.files.length;this.handlers.textRead.call(this)},textPrev(){const a=TEXT_AREAS[this.rt.textArea];this.rt.textFile=(this.rt.textFile+a.files.length-1)%a.files.length;this.handlers.textRead.call(this)},textSearch(){this.ask('Search file names and descriptions:',q=>{const s=q.toLowerCase(),r=[];TEXT_AREAS.forEach((a,ai)=>a.files.forEach((f,fi)=>{if((f[0]+' '+f[1]+' '+(f[3]||'')).toLowerCase().includes(s))r.push(`${ai+1}/${fi+1} ${f[0]} — ${f[1]}`)}));this.print('\n'+(r.join('\n')||'No matches.')+'\n');this.prompt()})},
