// All handlers are registered by name and initialization is guarded for test imports.
export function validateRegistry(){const seen=new Set(),errors=[];for(const c of COMMAND_REGISTRY){const id=`${c.context}:${c.key}`;if(seen.has(id))errors.push(`duplicate ${id}`);seen.add(id);if(!c.help||typeof BBSApp.prototype.handlers[c.handler]!=='function')errors.push(`invalid ${id}`)}return errors}
if(typeof document!=='undefined'&&document.getElementById('terminal'))new BBSApp(document);
export {BBSApp};
